{"content": "import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllStaff, createStaffAccount, updateStaffProfile, deleteStaffAccount } from '../../services/api.js';

function getAuthStaff() {
  const raw = localStorage.getItem('authStaff');
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

const emptyForm = { name: '', email: '', password: '', role: 'staff' };

export default function StaffManagement() {
  const navigate = useNavigate();
  const currentStaff = getAuthStaff();

  const [staffList, setStaffList] = useState([]);
  const [selected, setSelected] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  if (!currentStaff) {
    navigate('/login');
    return null;
  }
  if (currentStaff.role !== 'admin') {
    navigate('/profile');
    return null;
  }

  useEffect(() => {
    fetchStaff();
  }, []);

  const fetchStaff = async () => {
    try {
      const data = await getAllStaff(currentStaff.token);
      setStaffList(data);
    } catch (err) {
      setError(err.message || 'Unable to load staff');
    }
  };

  const handleCreate = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');

    try {
      await createStaffAccount(form, currentStaff.token);
      setStatus('Staff account created successfully');
      setForm(emptyForm);
      fetchStaff();
    } catch (err) {
      setError(err.message || 'Create staff failed');
    }
  };

  const handleSelect = (staff) => {
    setSelected(staff);
    setForm({
      name: staff.name || '',
      email: staff.email || '',
      password: '',
      role: staff.role || 'staff',
    });
    setStatus('Editing ' + staff.name);
    setError('');
  };

  const handleUpdate = async (event) => {
    event.preventDefault();
    if (!selected) return;
    setError('');
    setStatus('');

    try {
      const payload = { targetId: selected.id, name: form.name, email: form.email, role: form.role };
      if (form.password) payload.password = form.password;

      await updateStaffProfile(payload, currentStaff.token);
      setStatus('Staff account updated successfully');
      setSelected(null);
      setForm(emptyForm);
      fetchStaff();
    } catch (err) {
      setError(err.message || 'Update failed');
    }
  };

  const handleDelete = async (staffId) => {
    const confirmed = window.confirm('Delete this account?');
    if (!confirmed) return;
    setError('');
    setStatus('');

    try {
      await deleteStaffAccount({ targetId: staffId }, currentStaff.token);
      setStatus('Staff account deleted successfully');
      if (selected?.id === staffId) {
        setSelected(null);
        setForm(emptyForm);
      }
      fetchStaff();
    } catch (err) {
      setError(err.message || 'Delete staff failed');
    }
  };

  const handleCancelEdit = () => {
    setSelected(null);
    setForm(emptyForm);
    setStatus('');
    setError('');
  };

  return (
    <main className="auth-page">
      <section className="auth-card auth-card-wide">
        <header>
          <h1>Staff Management</h1>
          <p>Welcome back, {currentStaff.name}. Manage staff accounts below.</p>
        </header>

        {error && <p className="auth-error-text">{error}</p>}
        {status && <p className="auth-success-text">{status}</p>}

        <div className="staff-list">
          {staffList.length === 0 ? (
            <p className="auth-small-note">No staff accounts yet.</p>
          ) : (
            <table className="staff-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {staffList.map((staff) => (
                  <tr key={staff.id}>
                    <td>{staff.name}</td>
                    <td>{staff.email}</td>
                    <td>{staff.role}</td>
                    <td>
                      <button className="auth-button auth-button-secondary" type="button" onClick={() => handleSelect(staff)}>
                        Edit
                      </button>
                      <button className="auth-button auth-button-danger" type="button" onClick={() => handleDelete(staff.id)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        <h2>{selected ? 'Edit Staff Account' : 'Create Staff Account'}</h2>
        <form onSubmit={selected ? handleUpdate : handleCreate} className="auth-form">
          <label>
            Full Name
            <input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />
          </label>
          <label>
            Email
            <input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />
          </label>
          <label>
            Password
            <input
              type="password"
              value={form.password}
              onChange={(event) => setForm({ ...form, password: event.target.value })}
              placeholder={selected ? 'Leave blank to keep current password' : ''}
              required={!selected}
            />
          </label>
          <label>
            Role
            <select value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}>
              <option value="staff">Staff</option>
              <option value="admin">Admin</option>
            </select>
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          {status && <p className="auth-success-text">{status}</p>}
          <button className="auth-button" type="submit">
            {selected ? 'Update Staff Account' : 'Create Staff Account'}
          </button>
          {selected && (
            <button type="button" className="auth-button auth-button-secondary" onClick={handleCancelEdit}>
              Cancel
            </button>
          )}
        </form>
      </section>
    </main>
  );
}
