import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllStaff, createStaffAccount, updateStaffProfile, deleteStaffAccount } from '../../services/api.js';

function getAuthStaff() {
  const raw = localStorage.getItem('authStaff');
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

const emptyForm = { name: '', email: '', password: '' };

export default function ParticipantManagement() {
  const navigate = useNavigate();
  const currentStaff = getAuthStaff();

  const [participants, setParticipants] = useState([]);
  const [selected, setSelected] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  if (!currentStaff) {
    navigate('/login');
    return null;
  }
  if (currentStaff.role !== 'staff') {
    navigate('/profile');
    return null;
  }

  useEffect(() => {
    fetchAccounts();
  }, []);

  const fetchAccounts = async () => {
    try {
      const data = await getAllStaff(currentStaff.token);
      setParticipants(data.filter((account) => account.role === 'participant'));
    } catch (err) {
      setError(err.message || 'Unable to load participants');
    }
  };

  const handleCreate = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');

    try {
      await createStaffAccount(form, currentStaff.token);
      setStatus('Participant created successfully');
      setForm(emptyForm);
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Create participant failed');
    }
  };

  const handleSelect = (participant) => {
    setSelected(participant);
    setForm({
      name: participant.name || '',
      email: participant.email || '',
      password: '',
    });
    setStatus('Editing ' + participant.name);
    setError('');
  };

  const handleUpdate = async (event) => {
    event.preventDefault();
    if (!selected) return;
    setError('');
    setStatus('');

    try {
      const payload = { targetId: selected.id, name: form.name, email: form.email };
      if (form.password) payload.password = form.password;

      await updateStaffProfile(payload, currentStaff.token);
      setStatus('Participant updated successfully');
      setSelected(null);
      setForm(emptyForm);
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Update failed');
    }
  };

  const handleDelete = async (participantId) => {
    const confirmed = window.confirm('Delete this participant account?');
    if (!confirmed) return;
    setError('');
    setStatus('');

    try {
      await deleteStaffAccount({ targetId: participantId }, currentStaff.token);
      setStatus('Participant deleted successfully');
      if (selected?.id === participantId) {
        setSelected(null);
        setForm(emptyForm);
      }
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Delete participant failed');
    }
  };

  const handleCancelEdit = () => {
    setSelected(null);
    setForm(emptyForm);
    setStatus('');
    setError('');
  };

  return (
    <main className="auth-page">
      <section className="auth-card auth-card-wide">
        <header>
          <h1>Participant Management</h1>
          <p>Welcome back, {currentStaff.name}. Manage participant accounts below.</p>
        </header>

        {error && <p className="auth-error-text">{error}</p>}
        {status && <p className="auth-success-text">{status}</p>}

        <div className="staff-list">
          {participants.length === 0 ? (
            <p className="auth-small-note">No participants yet.</p>
          ) : (
            <table className="staff-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {participants.map((participant) => (
                  <tr key={participant.id}>
                    <td>{participant.name}</td>
                    <td>{participant.email}</td>
                    <td>
                      <button className="auth-button auth-button-secondary" type="button" onClick={() => handleSelect(participant)}>
                        Edit
                      </button>
                      <button className="auth-button auth-button-danger" type="button" onClick={() => handleDelete(participant.id)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        <h2>{selected ? 'Edit Participant' : 'Create Participant'}</h2>
        <form onSubmit={selected ? handleUpdate : handleCreate} className="auth-form">
          <label>
            Full Name
            <input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />
          </label>
          <label>
            Email
            <input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />
          </label>
          <label>
            Password
            <input
              type="password"
              value={form.password}
              onChange={(event) => setForm({ ...form, password: event.target.value })}
              placeholder={selected ? 'Leave blank to keep current password' : ''}
              required={!selected}
            />
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          {status && <p className="auth-success-text">{status}</p>}
          <button className="auth-button" type="submit">
            {selected ? 'Update Participant' : 'Create Participant'}
          </button>
          {selected && (
            <button type="button" className="auth-button auth-button-secondary" onClick={handleCancelEdit}>
              Cancel
            </button>
          )}
        </form>
      </section>
    </main>
  );
}

